var WORKSHEET_BUNDLE = {
  'module-01.html': '<div class="worksheet-card">\n    <h3>Worksheet 1 - Observations &amp; Risk Assessment</h3>\n    <p style="font-size:0.88rem;margin:0 0 1rem;color:var(--purple);">Complete all sections using your observations from the software activities and from inspecting the physical arm.</p>\n    <div class="ws-field">\n      <label>1. From Activity 1A - How many joints did you count on the 3D model?</label>\n      <input type="text" placeholder="e.g. 6 joints">\n    </div>\n    <div class="ws-field">\n      <label>2. From Activity 1A - How many links (rigid segments) did you count?</label>\n      <input type="text" placeholder="e.g. 6 links">\n    </div>\n    <div class="ws-field">\n      <label>3. What is the Degrees of Freedom (DoF) of the arm? (DoF = number of joints)</label>\n      <input type="text" placeholder="e.g. 6 DoF">\n    </div>\n    <div class="ws-field">\n      <label>4. Describe where you found the Torque Enable/Disable control in the app:</label>\n      <input type="text" placeholder="e.g. Joint Control tab, in the header area above the joint cards">\n    </div>\n    <div class="ws-field">\n      <label>5. What colour is the LED strip when the arm has torque disabled and is safe to approach? What colour indicates it is actively moving?</label>\n      <input type="text" placeholder="Safe to approach: ___ / Moving: ___">\n    </div>\n    <div class="ws-field">\n      <label>6. In your own words, why is it important to disable torque before manually adjusting the arm?</label>\n      <textarea placeholder="Write 1–2 sentences..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>7. Complete this risk assessment for operating the robot arm in your classroom:</label>\n    </div>\n    <table class="ws-table">\n      <thead>\n        <tr>\n          <th style="width:22%">Hazard</th>\n          <th style="width:16%">Likelihood<br>(L/M/H)</th>\n          <th style="width:16%">Severity<br>(L/M/H)</th>\n          <th style="width:14%">Risk Level</th>\n          <th style="width:32%">Control measure</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td><input type="text" value="Pinch at joint"></td>\n          <td><input type="text" placeholder="M"></td>\n          <td><input type="text" placeholder="H"></td>\n          <td><input type="text" placeholder="Medium"></td>\n          <td><input type="text" placeholder="Keep clear, low speed..."></td>\n        </tr>\n        <tr>\n          <td><input type="text" placeholder="Your hazard 2"></td>\n          <td><input type="text" placeholder="L/M/H"></td>\n          <td><input type="text" placeholder="L/M/H"></td>\n          <td><input type="text" placeholder=""></td>\n          <td><input type="text" placeholder="Control measure..."></td>\n        </tr>\n        <tr>\n          <td><input type="text" placeholder="Your hazard 3"></td>\n          <td><input type="text" placeholder="L/M/H"></td>\n          <td><input type="text" placeholder="L/M/H"></td>\n          <td><input type="text" placeholder=""></td>\n          <td><input type="text" placeholder="Control measure..."></td>\n        </tr>\n        <tr>\n          <td><input type="text" placeholder="Your hazard 4"></td>\n          <td><input type="text" placeholder="L/M/H"></td>\n          <td><input type="text" placeholder="L/M/H"></td>\n          <td><input type="text" placeholder=""></td>\n          <td><input type="text" placeholder="Control measure..."></td>\n        </tr>\n      </tbody>\n    </table>\n    <div class="ws-field">\n      <label>8. What PPE is required when operating the robot arm in this lab? List at least three items.</label>\n      <textarea placeholder="1. Safety glasses&#10;2. &#10;3. "></textarea>\n    </div>\n    <div class="ws-field">\n      <label>9. Extension: Compare the working envelope of our arm with one industrial robot you have researched. How do the safety requirements differ?</label>\n      <textarea style="min-height:90px;" placeholder="Research an industrial arm (e.g. KUKA KR6, Universal Robots UR5) and compare..."></textarea>\n    </div>\n  </div>',

  'module-02.html': '<div class="worksheet-card">\n    <h3>Worksheet 2 - Mechanical Structure &amp; Materials</h3>\n    <div class="ws-field">\n      <label>1. Sketch the arm from the side (use the 3D view as reference). Label each link and joint with numbers:</label>\n      <textarea style="min-height:120px;" placeholder="Describe or sketch here. Label: Base, Link 1, Joint 1, Link 2, Joint 2, ... End Effector"></textarea>\n    </div>\n    <div class="ws-field">\n      <label>2. Record the approximate link lengths and joint ranges from Activity 2A:</label>\n    </div>\n    <table class="ws-table">\n      <thead><tr><th>Segment</th><th>Approx. length (mm)</th><th>Joint min (°)</th><th>Joint max (°)</th><th>Total range (°)</th></tr></thead>\n      <tbody>\n        <tr><td><input type="text" value="Link 1 (base to shoulder)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n        <tr><td><input type="text" value="Link 2 (shoulder to elbow)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n        <tr><td><input type="text" value="Link 3 (elbow to wrist)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n        <tr><td><input type="text" value="Link 4 (wrist pitch)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n        <tr><td><input type="text" value="Link 5 (wrist roll)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n        <tr><td><input type="text" value="Link 6 (wrist to EE)"></td><td><input type="text" placeholder="mm"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n      </tbody>\n    </table>\n    <div class="ws-field">\n      <label>3. What material are most of the structural links on your robot arm made from? How did you identify this?</label>\n      <input type="text" placeholder="Material: ...  Identified by: ...">\n    </div>\n    <div class="ws-field">\n      <label>4. A motor produces 0.15 Nm of torque. If the gearbox ratio is 40:1, what is the output torque (ignoring losses)?</label>\n      <input type="text" placeholder="Output torque = ___ Nm  (Show working: 0.15 × 40 = ___)">\n    </div>\n    <div class="ws-field">\n      <label>5. Explain why it is better to place heavy components (like motors) near the base of the arm rather than near the end effector.</label>\n      <textarea placeholder="Because..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>6. Describe what backlash is and explain one way it could affect the accuracy of a pick-and-place task.</label>\n      <textarea placeholder="Backlash is... It affects accuracy because..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>7. Extension: Our arm is a serial kinematic chain. Research one parallel robot design (e.g. a delta robot). Describe one advantage and one disadvantage compared to a serial arm.</label>\n      <textarea placeholder="Parallel robot: ... Advantage: ... Disadvantage: ..."></textarea>\n    </div>\n  </div>',

  'module-03.html': '<div class="worksheet-card">\n    <h3>Worksheet 3 - Electrical Systems &amp; Live Data</h3>\n    <div class="ws-field">\n      <label>1. What IP address did you use to connect to the onboard computer?</label>\n      <input type="text" placeholder="e.g. 192.168.1.42">\n    </div>\n    <div class="ws-field">\n      <label>2. What connection port does the Robot Arm server use? Why is a specific port number needed?</label>\n      <textarea placeholder="Port: ___  Reason: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>3. Record the live joint data you read in Activity 3B:</label>\n    </div>\n    <table class="ws-table">\n      <thead>\n        <tr>\n          <th>Joint</th>\n          <th>Current Angle (°)</th>\n          <th>Temperature (°C)</th>\n          <th>Supply Voltage (V)</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr><td><input type="text" value="Joint 1"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr>\n        <tr><td><input type="text" value="Joint 2"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr>\n        <tr><td><input type="text" value="Joint 3"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr>\n        <tr><td><input type="text" value="Joint 4"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr>\n        <tr><td><input type="text" value="Joint 5"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr>\n        <tr><td><input type="text" value="Joint 6"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°C"></td><td><input type="text" placeholder="V"></td></tr>\n      </tbody>\n    </table>\n    <div class="ws-field">\n      <label>4. The joint status is updated about every 20 ms. Convert this interval to a frequency in Hz.</label>\n      <input type="text" placeholder="Interval: ___ ms → Frequency: ___ Hz">\n    </div>\n    <div class="ws-field">\n      <label>5. Explain the difference between half-duplex and full-duplex serial communication. Why does the servo bus use half-duplex?</label>\n      <textarea placeholder="Half-duplex means... Full-duplex means... The servo bus uses half-duplex because..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>6. Give one example of open-loop control and one example of closed-loop control from everyday life (not from the robot arm).</label>\n      <textarea placeholder="Open-loop example: ...&#10;Closed-loop example: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>7. The arm\'s servos use PID control internally. If the arm is at 30° and you command it to move to 90°, what is the initial error value that the PID controller sees?</label>\n      <input type="text" placeholder="Error = ___ °">\n    </div>\n    <div class="ws-field">\n      <label>8. Extension: Draw a block diagram of the closed-loop control system for one joint of the robot arm, from command input through to mechanical output. Label all blocks and signals.</label>\n      <textarea style="min-height:100px;" placeholder="Describe or sketch your block diagram here. Include: setpoint, error, controller, amplifier, motor, encoder, feedback path..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>9. Using section 3.6, choose the most suitable sensor for each task. State whether it is tactile or non-tactile and give a reason for your choice.</label>\n    </div>\n    <table class="ws-table">\n      <thead>\n        <tr>\n          <th>Task</th>\n          <th>Sensor chosen</th>\n          <th>Tactile / Non-tactile</th>\n          <th>Reason</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr><td><input type="text" value="Detect steel brackets on a conveyor"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="Detect plastic bottles on a conveyor"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="Measure how hard the gripper squeezes a part"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="Stop an axis before it hits its end stop"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="Stop the robot if a person enters the cell"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n      </tbody>\n    </table>\n    <div class="ws-field">\n      <label>10. Explain why an inductive proximity sensor would not detect a plastic part, but a capacitive proximity sensor would.</label>\n      <textarea placeholder="An inductive sensor works by... A capacitive sensor works by..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>11. Research: Find the datasheet for a real industrial sensor that is <em>not</em> used on the robot arm. Record its details and suggest one way it could be used with a robot.</label>\n      <textarea style="min-height:100px;" placeholder="Sensor and manufacturer: ...&#10;Tactile or non-tactile: ...&#10;Operating principle: ...&#10;Supply voltage: ...&#10;Output type (digital / analogue, PNP / NPN): ...&#10;Sensing range: ...&#10;How it could be used with a robot: ..."></textarea>\n    </div>\n  </div>',

  'module-04.html': '<div class="worksheet-card">\n    <h3>Worksheet 4 - HMI Exploration &amp; Programming</h3>\n    <div class="ws-field">\n      <label>1. Record the range of motion for each joint from Activity 4A:</label>\n    </div>\n    <table class="ws-table">\n      <thead>\n        <tr>\n          <th>Joint</th>\n          <th>Minimum angle (°)</th>\n          <th>Maximum angle (°)</th>\n          <th>Total range (°)</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr><td><input type="text" value="Joint 1 (Base)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n        <tr><td><input type="text" value="Joint 2 (Shoulder)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n        <tr><td><input type="text" value="Joint 3 (Elbow)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n        <tr><td><input type="text" value="Joint 4 (Wrist)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n        <tr><td><input type="text" value="Joint 5 (Wrist Pitch)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n        <tr><td><input type="text" value="Joint 6 (Wrist Roll)"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td><td><input type="text" placeholder="°"></td></tr>\n      </tbody>\n    </table>\n    <div class="ws-field">\n      <label>2. In the Pendant Control tab, what happened to the arm\'s movement when you reduced speed to 20%? How did it feel different from 100%?</label>\n      <textarea placeholder="At 100% speed, the arm... At 20% speed, the arm..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>3. Describe the sequence of blocks in your Blockly program from Activity 4B (the looping version):</label>\n      <textarea placeholder="1. Move to position 0 (Home)&#10;2. Wait 1000 ms&#10;3. ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>4. What is the difference between sequential and event-driven programming? Give one example of each from the robot arm application.</label>\n      <textarea placeholder="Sequential: ...&#10;Event-driven: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>5. List three features of the Robot Arm application that you think are good HMI design, and explain why for each.</label>\n      <textarea style="min-height:100px;" placeholder="1. Feature: ... Why it\'s good: ...&#10;2. Feature: ... Why it\'s good: ...&#10;3. Feature: ... Why it\'s good: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>6. List one feature you think could be improved in the application\'s HMI design. What would you change, and why?</label>\n      <textarea placeholder="Feature to improve: ...&#10;My proposed change: ...&#10;Why this would be better: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>7. The IEC 60073 standard specifies colour meanings for industrial controls. Why does a standard like this matter for safety? What could go wrong if each manufacturer used different colour conventions?</label>\n      <textarea placeholder="Standards matter because... If each manufacturer used different colours..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>8. Extension: The Stored Positions feature allows up to 100 positions to be saved. Design a pick-and-place sequence (on paper or in Blockly) that sorts objects into two locations based on a condition. Describe your logic here.</label>\n      <textarea style="min-height:110px;" placeholder="Describe your sorting sequence: what positions you would define, what the loop logic would be, and how a conditional (if/else) would work in your program..."></textarea>\n    </div>\n  </div>',

  'module-05.html': '<div class="worksheet-card">\n    <h3>Worksheet 5 - Forces &amp; Load Analysis</h3>\n    <div class="ws-field">\n      <label>1. Record the load readings for each pose from Activity 5A:</label>\n    </div>\n    <table class="ws-table">\n      <thead><tr><th>Pose</th><th>Joint 1 Load</th><th>Joint 2 Load</th><th>Joint 3 Load</th><th>Joint 4 Load</th><th>Joint 5 Load</th><th>Joint 6 Load</th></tr></thead>\n      <tbody>\n        <tr><td><input type="text" value="Horizontal"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td></tr>\n        <tr><td><input type="text" value="45° elevation"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td></tr>\n        <tr><td><input type="text" value="Vertical (up)"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="%"></td></tr>\n      </tbody>\n    </table>\n    <div class="ws-field">\n      <label>2. Which joint showed the highest load in the horizontal pose? Why would you expect this?</label>\n      <textarea placeholder="Joint ___ had the highest load because..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>3. Calculate the moment at the shoulder joint (Joint 2) when the arm is horizontal. Use: Link 2 mass = 0.18 kg, length = 0.12 m; Link 3 mass = 0.12 kg, distance from shoulder = 0.22 m; Link 4 mass = 0.08 kg, distance from shoulder = 0.30 m. (Take g = 9.81 m/s². Hint: add the moment from each link.)</label>\n      <textarea placeholder="M_link2 = 0.18 × 9.81 × 0.06 = ___ Nm&#10;M_link3 = 0.12 × 9.81 × 0.22 = ___ Nm&#10;M_link4 = 0.08 × 9.81 × 0.30 = ___ Nm&#10;Total = ___ Nm"></textarea>\n    </div>\n    <div class="ws-field">\n      <label>4. If a 150 g payload is added at the end effector (0.35 m from the shoulder), what extra moment does this add at the shoulder? Show your working.</label>\n      <input type="text" placeholder="Extra moment = 0.150 × 9.81 × 0.35 = ___ Nm">\n    </div>\n    <div class="ws-field">\n      <label>5. Explain in your own words why the load on the shoulder joint decreases as the arm is raised from horizontal to vertical.</label>\n      <textarea placeholder="As the arm rises, the perpendicular distance (moment arm) from the shoulder joint to the weight vectors..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>6. Extension: Sketch a free body diagram for the elbow joint (Joint 3) when the arm is horizontal. Label the forces and moment arms. What torque must the elbow servo produce?</label>\n      <textarea style="min-height:100px;" placeholder="Sketch and describe your FBD here. Include weights of Link 3, Link 4, and the moment arm distances."></textarea>\n    </div>\n  </div>',

  'module-06.html': '<div class="worksheet-card">\n    <h3>Worksheet 6 - Industrial Context &amp; Automation Cell</h3>\n    <div class="ws-field">\n      <label>1. Sketch your automation cell layout (top view). Label: robot arm base, Home position, Pick position, Place position, safety boundary.</label>\n      <textarea style="min-height:110px;" placeholder="Describe or sketch your layout. Include approximate distances and the arm\'s working envelope boundary."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>2. What was the cycle time (seconds) for one Home → Pick → Place → Home sequence?</label>\n      <input type="text" placeholder="Cycle time = ___ s  →  ___ cycles/min  →  ___ cycles/hour">\n    </div>\n    <div class="ws-field">\n      <label>3. What level of automation does your programmed sequence represent? Justify your answer.</label>\n      <textarea placeholder="The sequence represents ___ automation because..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>4. Compare the articulated arm and the SCARA robot. For which of these tasks would each be better suited, and why?<br>Task A: Welding a curved seam on a 3D part. Task B: Placing chips onto flat PCBs at 60 per minute.</label>\n      <textarea placeholder="Task A: best suited to ___ because...&#10;Task B: best suited to ___ because..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>5. What safety measures would you add to your cell if it were to run unattended overnight?</label>\n      <textarea placeholder="1. &#10;2. &#10;3. "></textarea>\n    </div>\n    <div class="ws-field">\n      <label>6. Extension: Research the IFR (International Federation of Robotics) statistics for global robot installations in the most recent year available. Which industry sector installs the most robots, and what type are they predominantly?</label>\n      <textarea placeholder="Source: ...  Sector: ...  Robot type: ...  Number installed: ..."></textarea>\n    </div>\n  </div>',

  'module-07.html': '<div class="worksheet-card">\n    <h3>Worksheet 7 - Kinematics Exploration</h3>\n    <div class="ws-field">\n      <label>1. Record end-effector positions for different joint angle combinations:</label>\n    </div>\n    <table class="ws-table">\n      <thead><tr><th>θ₁ (°)</th><th>θ₂ (°)</th><th>θ₃ (°)</th><th>θ₄ (°)</th><th>θ₅ (°)</th><th>θ₆ (°)</th><th>X (mm)</th><th>Y (mm)</th><th>Z (mm)</th></tr></thead>\n      <tbody>\n        <tr><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td></tr>\n        <tr><td><input type="text" value="90"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td></tr>\n        <tr><td><input type="text" value="0"></td><td><input type="text" value="45"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" value="0"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td></tr>\n        <tr><td><input type="text" placeholder="your choice"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td></tr>\n        <tr><td><input type="text" placeholder="max X pose"></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td><td><input type="text" placeholder=""></td></tr>\n      </tbody>\n    </table>\n    <div class="ws-field">\n      <label>2. When you rotated Joint 1 to 90°, did Z change? Explain why or why not in terms of what Joint 1 controls.</label>\n      <textarea placeholder="Z did / did not change because Joint 1 (base rotation) controls rotation about the vertical axis, so..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>3. Forward kinematics is described as a one-way calculation: from joint angles → end-effector position. What would the reverse calculation (end-effector position → joint angles) be called, and why might it be more difficult?</label>\n      <textarea placeholder="The reverse is called... It is harder because..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>4. In the 4×4 transformation matrix shown in the Kinematics tab, what do the values in the rightmost column (tx, ty, tz) represent?</label>\n      <input type="text" placeholder="They represent...">\n    </div>\n    <div class="ws-field">\n      <label>5. For a simple 2-link planar arm with L₁ = 150 mm, L₂ = 100 mm, θ₁ = 30°, θ₂ = 45°, calculate X and Y using the formulae from section 7.2. Show your working.</label>\n      <textarea placeholder="θ₁ + θ₂ = 75°&#10;X = 150·cos(30°) + 100·cos(75°) = ___ + ___ = ___ mm&#10;Y = 150·sin(30°) + 100·sin(75°) = ___ + ___ = ___ mm"></textarea>\n    </div>\n    <div class="ws-field">\n      <label>6. Extension: The arm has a maximum reach (furthest X from base). Using the link lengths you measured in Module 2, calculate the theoretical maximum X reach with all joints extended horizontally.</label>\n      <textarea placeholder="Maximum reach = L₁ + L₂ + L₃ + L₄ = ___ + ___ + ___ + ___ = ___ mm&#10;Compare this to what you measured in the Kinematics tab..."></textarea>\n    </div>\n  </div>',

  'module-08.html': '<div class="worksheet-card">\n    <h3>Worksheet 8 - Control &amp; Communication</h3>\n    <div class="ws-field">\n      <label>1. Describe what you observed at 10%, 50%, and 100% speed for the 0°→60° move on Joint 2:</label>\n      <textarea placeholder="10%: ...&#10;50%: ...&#10;100%: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>2. Did the joint overshoot at high speed? If so, explain this in terms of PID control - which term is responsible for reducing overshoot?</label>\n      <textarea placeholder="Overshoot at high speed occurs because... The ___ (P/I/D) term reduces overshoot by..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>3. Explain in your own words the difference between joint interpolation and linear interpolation. Give one application where each would be the better choice.</label>\n      <textarea placeholder="Joint interpolation: ... best for...&#10;Linear interpolation: ... best for..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>4. The full communication path for a move command goes: App → WebSocket → Onboard computer → Serial bus → Servo. At each step, describe what form the data takes and any key parameters (e.g. JSON, angle value, servo ID).</label>\n      <textarea placeholder="App: click \'Move to 60°\' → generates JSON message {joint:2, angle:60, speed:50}&#10;WebSocket: transmits JSON over TCP to port 8080&#10;Onboard computer: receives JSON, parses it, formats ST3215 serial packet...&#10;Serial bus: ...&#10;Servo: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>5. If the D (derivative) gain is set too high, what would you expect to see in the arm\'s motion? Why?</label>\n      <input type="text" placeholder="Too high D gain would cause... because D reacts to...">\n    </div>\n    <div class="ws-field">\n      <label>6. Extension: The onboard computer polls each servo at a set interval. If the interval is 100 ms, what is the maximum frequency at which position updates are received? Could this cause problems for high-speed moves?</label>\n      <textarea placeholder="100 ms interval = ___ Hz update rate. For a fast move this could cause... because..."></textarea>\n    </div>\n  </div>',

  'module-09.html': '<div class="worksheet-card">\n    <h3>Worksheet 9 - Software Architecture &amp; G-code</h3>\n    <div class="ws-field">\n      <label>1. Draw a diagram of the software layers in the robot arm system. Label each layer and the communication mechanism between them.</label>\n      <textarea style="min-height:100px;" placeholder="Layers (top to bottom):&#10;1. Electron App (JavaScript) ← runs on PC&#10;2. WebSocket (JSON over TCP/8080)&#10;3. Server (onboard computer)&#10;4. Serial bus (UART, 1 Mbaud)&#10;5. ST3215 Servos"></textarea>\n    </div>\n    <div class="ws-field">\n      <label>2. Write a G-code program that moves the arm from home to three positions (A, B, C) and back to home, with a 1-second dwell at each position. Use the joint angles you used as stored positions in Module 6.</label>\n      <textarea style="min-height:130px;" placeholder="; Your G-code program&#10;G28&#10;G04 P500&#10;G01 J1=___ J2=___ F___  ; Move to A&#10;..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>3. What is the purpose of the M30 command at the end of a G-code file?</label>\n      <input type="text" placeholder="M30 signals...">\n    </div>\n    <div class="ws-field">\n      <label>4. Compare Blockly and G-code: in which situation would you choose each one, and what is the key limitation of each?</label>\n      <textarea placeholder="Blockly: best when... limitation: ...&#10;G-code: best when... limitation: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>5. The app uses a WebSocket rather than a simple HTTP request to communicate with the onboard computer. What is the key advantage of WebSocket over HTTP for this application?</label>\n      <textarea placeholder="WebSocket is better here because... HTTP would be a problem because..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>6. Extension: Look at the G-code tab in the application. What happens if a G-code command contains a joint angle outside the servo\'s range? How should this be handled, and where in the software stack should the check occur?</label>\n      <textarea placeholder="If an out-of-range angle is commanded... The check should occur at... because..."></textarea>\n    </div>\n  </div>',

  'module-10.html': '<div class="worksheet-card">\n    <h3>Worksheet 10 - Machine Vision &amp; Vision-Guided Picking</h3>\n    <div class="ws-field">\n      <label>1. Activity 10A - Record the Detected blocks table:</label>\n    </div>\n    <table class="ws-table">\n      <thead>\n        <tr>\n          <th>Index</th>\n          <th>Colour</th>\n          <th>X (mm)</th>\n          <th>Y (mm)</th>\n          <th>Rotation (°)</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr><td><input type="text" value="0"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="1"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="2"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="3"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n      </tbody>\n    </table>\n    <div class="ws-field">\n      <label>2. Activity 10A - What happened when you covered one marker? What happened when you covered two? Explain why.</label>\n      <textarea placeholder="One marker covered: ...&#10;Two markers covered: ...&#10;Because..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>3. Activity 10B - Record your colour detection tests:</label>\n    </div>\n    <table class="ws-table">\n      <thead>\n        <tr>\n          <th>Test</th>\n          <th>All blocks detected? (Y/N)</th>\n          <th>Colours correct? (Y/N)</th>\n          <th>Notes</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr><td><input type="text" value="Normal room lighting"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="Shadow across blocks"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="Torch glare"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="Non-block coloured object"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n      </tbody>\n    </table>\n    <div class="ws-field">\n      <label>4. Activity 10B - How long did a new block take to appear? Use the detection rate (about 5 per second) and the 5-frame rule to explain the delay. What is the advantage and disadvantage of this rule?</label>\n      <textarea placeholder="Time to appear: ___ s&#10;Explanation: ...&#10;Advantage: ...  Disadvantage: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>5. Explain why the vision system uses HSV rather than RGB to find coloured blocks.</label>\n      <textarea placeholder="When lighting changes, RGB values... whereas in HSV..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>6. Activity 10C - Record your accuracy measurements:</label>\n    </div>\n    <table class="ws-table">\n      <thead>\n        <tr>\n          <th>Block position</th>\n          <th>Ruler X</th>\n          <th>Ruler Y</th>\n          <th>Camera X</th>\n          <th>Camera Y</th>\n          <th>Error (mm)</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr><td><input type="text" value="Near origin"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="Centre of mat"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="Far corner (4 markers)"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text" value="Far corner (3 markers)"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n      </tbody>\n    </table>\n    <div class="ws-field">\n      <label>7. Activity 10C - Where on the mat was the camera most and least accurate? Suggest two reasons for the difference.</label>\n      <textarea placeholder="Most accurate: ...  Least accurate: ...&#10;Reasons: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>8. Activity 10D - Record the offset between the gripper and the block. Was it a systematic error or a random error? How do you know?</label>\n      <textarea placeholder="Offset X: ___ mm  Offset Y: ___ mm&#10;Type of error: ...  Because..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>9. The camera cannot measure a block\'s height. Explain why, and describe one way an industrial system could find the height of a part.</label>\n      <textarea placeholder="The camera cannot measure height because...&#10;An industrial system could..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>10. Machine vision is used for inspection, identification and guidance. Give one industrial example of each that is different from the examples in section 10.1. Which of the three could this arm\'s camera be extended to do next, and what would need to change?</label>\n      <textarea style="min-height:100px;" placeholder="Inspection: ...&#10;Identification: ...&#10;Guidance: ...&#10;Next step for this arm: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>11. Extension: Write or describe a program that picks every visible block and sorts them by colour into separate drop-off positions. Which programming mode did you use, and why?</label>\n      <textarea style="min-height:100px;" placeholder="Programming mode: ...  Reason: ...&#10;Program outline: ..."></textarea>\n    </div>\n  </div>',

  'module-11.html': '<div class="section-card worksheet-card">\n    <span class="pill pill-worksheet">Worksheet</span>\n    <h2>Activity - Live Data Monitoring</h2>\n    <p>You will observe live servo telemetry while the arm performs a repeating motion, and record what you see.</p>\n    <ul class="steps">\n      <li>Connect to the arm using the <span class="tab-ref">Connection</span> tab. Confirm the status indicator is green.</li>\n      <li>Open the <span class="tab-ref">Joint Control</span> tab. Note the servo status panel - locate the live position, load, voltage and temperature readouts for each joint.</li>\n      <li>With the arm at its home/zero position, record the <strong>idle readings</strong> in the table below.</li>\n      <li>Command Joint 2 (shoulder) to move slowly between 0° and 60°, repeatedly. Observe how the load value changes at the extremes of the motion.</li>\n      <li>Now hold the end-effector gently (add a small manual load) and observe load % again. Record the difference.</li>\n      <li>Check the temperature reading before and after 5 minutes of continuous motion. Is it rising?</li>\n      <li>Open the <span class="tab-ref">Calibration</span> tab, select Joint 2 and click <strong>Read Registers</strong>. The protection thresholds live in the servo itself: find <strong>Max temperature limit</strong> (0x0D), <strong>Protection current</strong> (0x1C) and <strong>Overload torque</strong> (0x24) in the EEPROM table and note their values. Compare them with the temperature and load you recorded.</li>\n    </ul>\n    <h3>Data Recording Table</h3>\n    <table>\n      <tr><th>Condition</th><th>Joint 2 Load %</th><th>Voltage (V)</th><th>Temperature (°C)</th></tr>\n      <tr><td>Idle / home</td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="V"></td><td><input type="text" placeholder="°C"></td></tr>\n      <tr><td>Moving 0°→60° (no load)</td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="V"></td><td><input type="text" placeholder="°C"></td></tr>\n      <tr><td>Moving with manual load</td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="V"></td><td><input type="text" placeholder="°C"></td></tr>\n      <tr><td>After 5 min continuous</td><td><input type="text" placeholder="%"></td><td><input type="text" placeholder="V"></td><td><input type="text" placeholder="°C"></td></tr>\n    </table>\n    <div class="ws-field">\n      <label>Observations - load change, temperature trend, and the servo\'s protection thresholds</label>\n      <textarea placeholder="Describe what you observed for load %, temperature, and the Max temperature limit / Protection current / Overload torque values from the Calibration tab..."></textarea>\n    </div>\n    <div class="callout callout-info no-print">\n      <span class="callout-icon">📊</span>\n      <div class="callout-body">\n        <strong>Joint Control Tab - Confirmed Layout</strong></br>\n        The <span class="ui-ref">Joint Control</span> tab shows six joint status cards (one per joint). Each card displays live data updated approximately every 20 ms from the servo bus:\n        <ul style="margin:0.4rem 0 0;padding-left:1.2rem;">\n          <li><strong>Angle (°)</strong> - current joint position</li>\n          <li><strong>Velocity</strong> - current speed</li>\n          <li><strong>Load (%)</strong> - current draw as a percentage of stall torque</li>\n          <li><strong>Voltage (V)</strong> - servo supply voltage</li>\n          <li><strong>Temperature (°C)</strong> - servo motor temperature</li>\n        </ul>\n        Note: the app has no alarm-threshold sliders of its own. The thermal and overload protection is built into each servo and its thresholds are stored in the servo\'s EEPROM - the <span class="ui-ref">Calibration</span> tab reads them directly from the hardware (Max temperature limit, Protection current, Overload torque, Protection time). Changing them needs the control password.\n      </div>\n    </div>\n  </div>',

  'module-12.html': '<div class="section-card worksheet-card">\n    <span class="pill pill-worksheet">Worksheet</span>\n    <h2>Activity - Full-System Trace</h2>\n    <p>You will trace a single user action through all five layers of the system, observing what happens at each stage.</p>\n    <ul class="steps">\n      <li>Open the app and connect to the arm via the <span class="tab-ref">Connection</span> tab. Note the connection status - this confirms layers 1–2 are working.</li>\n      <li>Navigate to the <span class="tab-ref">3D Visualization</span> tab. This shows the forward kinematics model (layer 3/5 - the software model).</li>\n      <li><p>Click the <strong>Pop Out</strong> button in the <span class="ui-ref">3D Visualisation</span> tab to open the 3D model in a separate always-on-top window. Arrange this alongside the main app window showing <span class="ui-ref">Joint Control</span>. Now, when you command Joint 1 to move 30°, you can simultaneously watch the 3D model update, the live angle readout change, and the load % respond - three data streams from three system layers, all in one view.</p></li>\n      <li>Open the <span class="tab-ref">Joint Control</span> tab alongside. Command Joint 1 to move 30°. Simultaneously watch: (a) the 3D model update, (b) the live position readout, (c) the load value change mid-move.</li>\n      <li>Now use the <span class="tab-ref">G-Code Control</span> tab to run a short two-move program. This exercises layers 1→5 with a programmatic sequence rather than manual input.</li>\n      <li>Use the <span class="tab-ref">Visual Programming</span> (Blockly) tab to build the same two moves as a block program. Compare: which interface felt more reliable? Which was faster to create?</li>\n      <li>Finally, open the <span class="tab-ref">Kinematics</span> tab. Enter the joint angles you used and confirm the displayed XYZ coordinates match where the arm physically ended up. This closes the loop between software model and physical reality.</li>\n    </ul>\n    <h3>Reflection Questions</h3>\n    <div class="ws-field">\n      <label>1. Which layer introduced the most noticeable delay? How did you detect it?</label>\n      <textarea placeholder="Your answer..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>2. Did the 3D model always match the physical arm position? If not, what might cause discrepancy?</label>\n      <textarea placeholder="Your answer..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>3. What would happen if the Python server crashed mid-move? Which layer would stop first?</label>\n      <textarea placeholder="Your answer..."></textarea>\n    </div>\n  </div>',

  'module-13.html': '<div class="section-card worksheet-card">\n    <span class="pill pill-worksheet">Worksheet</span>\n    <h2>Activity - Design Your Own Work Cell</h2>\n    <p>You will define a safe operating envelope, store key positions, and write a G-code program to run a repeating cycle.</p>\n    <ul class="steps">\n      <li>Open the <span class="tab-ref">Dead Zones</span> tab. Review the current joint limits. Sketch the physical workspace on paper and identify any areas to avoid (cables, bench edges, other equipment). Adjust limits if needed.</li>\n      <li>Open the <span class="tab-ref">Joint Control</span> tab and jog the arm to four key positions for a pick-and-place task: <strong>Home</strong>, <strong>Pick Above</strong>, <strong>Pick</strong>, <strong>Place Above</strong>. Write down the joint angles for each.</li>\n      <li>Open the <span class="tab-ref">Stored Positions</span> tab. Save each of the four positions with a descriptive name.</li>\n      <li>Open the <span class="tab-ref">G-Code Control</span> tab. Write a program using the joint angles you recorded to perform one complete pick-and-place cycle. Use G04 with a dwell time at the pick and place points to simulate gripper action.</li>\n      <li>Run the program at 25% speed first. Check for any joint limit warnings or unexpected motion. Gradually increase to 75%.</li>\n      <li>Time the cycle at 50% and 75% speed. Calculate the <strong>cycle time</strong> (time for one complete pick-and-place).</li>\n      <li><p>Rewrite the pick and place points as Cartesian targets (<code>G1 X.. Y.. Z.. F..</code>) instead of joint angles. Then, on the <span class="ui-ref">Pendant Control</span> tab\'s <strong>Movement Mode</strong> card, switch between <strong>PTP</strong> and <strong>Linear Cartesian</strong> and repeat the cycle time test at 50% speed in both modes. Record both times. Linear Cartesian will typically be slower - the app computes Cartesian waypoints to keep the tool moving in a straight line. Note this in your cycle time table alongside the path quality (use the End-Effector Trace in 3D Visualisation to compare path straightness).</p></li>\n    </ul>\n    <div class="callout callout-info no-print">\n      <span class="callout-icon">🔢</span>\n      <div class="callout-body">\n        <strong>Speed Units - G-code vs Blockly</strong></br>\n        Speed is expressed differently depending on which programming mode you use:\n        <ul style="margin:0.4rem 0 0;padding-left:1.2rem;">\n          <li><strong>G-Code</strong>: the F parameter is in <strong>steps per second</strong> (e.g. <code>G1 J2=45 F500</code> - 500 steps/sec ≈ 44°/sec)</li>\n          <li><strong>Blockly</strong>: speed is set in <strong>degrees per second</strong> (automatically converted to steps/sec using the ratio 11.37 steps/degree)</li>\n        </ul>\n        To convert: multiply degrees/sec by 11.37 to get steps/sec. For example, 100°/sec = F1137 in G-code.\n      </div>\n    </div>\n    <h3>Cell Design Record</h3>\n    <table>\n      <tr><th>Position name</th><th>J1 (°)</th><th>J2 (°)</th><th>J3 (°)</th><th>J4 (°)</th></tr>\n      <tr><td>Home</td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n      <tr><td>Pick Above</td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n      <tr><td>Pick</td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n      <tr><td>Place Above</td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n    </table>\n    <table>\n      <tr><th>Speed setting</th><th>Cycle time (s)</th><th>Observations</th></tr>\n      <tr><td>25%</td><td><input type="text"></td><td><input type="text"></td></tr>\n      <tr><td>50%</td><td><input type="text"></td><td><input type="text"></td></tr>\n      <tr><td>75%</td><td><input type="text"></td><td><input type="text"></td></tr>\n      <tr><td>50% PTP</td><td><input type="text"></td><td><input type="text"></td></tr>\n      <tr><td>50% Linear Cartesian</td><td><input type="text"></td><td><input type="text"></td></tr>\n    </table>\n    <div class="callout callout-info no-print">\n      <span class="callout-icon">🚫</span>\n      <div class="callout-body">\n        <strong>Dead Zones Tab - Confirmed Parameters</strong></br>\n        Dead zones are defined as <strong>named rectangular XYZ exclusion volumes</strong>. Each zone has:\n        <ul style="margin:0.4rem 0 0;padding-left:1.2rem;">\n          <li>A user-defined <strong>name</strong> (e.g. "TableEdge", "CableRun")</li>\n          <li><strong>X min/max, Y min/max, Z min/max</strong> bounds in millimetres (Cartesian coordinates)</li>\n          <li>An <strong>enable/disable toggle</strong> per zone - disabled zones are ignored during path planning</li>\n        </ul>\n        When a planned move would pass through an active dead zone, the server automatically routes the path over the zone via a safe Z height. Enable the <strong>Dead Zones</strong> overlay in 3D Visualisation to see the defined volumes as coloured boxes in the 3D model.\n      </div>\n    </div>\n  </div>',

  'module-14.html': '<div class="section-card worksheet-card">\n    <span class="pill pill-worksheet">Worksheet</span>\n    <h2>Activity - Safety Audit of the Arm</h2>\n    <p>Carry out a systematic safety review of the arm setup in your lab, applying the hierarchy of controls.</p>\n    <ul class="steps">\n      <li>Identify three specific hazards associated with this arm (e.g. struck by moving link, trapped fingers, tripping on cables). Write each below.</li>\n      <li>For each hazard, classify it using the hierarchy: which existing controls are in place? Which level of the hierarchy are they at?</li>\n      <li>Open the <span class="tab-ref">Dead Zones</span> tab. Check that joint limits are set appropriately. Does the current limit prevent the arm reaching any fixtures or people in your lab layout?</li>\n      <li>Open the <span class="tab-ref">Calibration</span> tab, select Joint 2 and click <strong>Read Registers</strong>. Record the servo\'s own protection settings from the EEPROM table: <strong>Max torque</strong> (0x10), <strong>Protection current</strong> (0x1C) and <strong>Overload torque</strong> (0x24). Note: there is no current-limit slider in the app - these limits live in the servo hardware and need the control password to change. The closest everyday software safety control for overload is the speed you choose for each move.</li>\n      <li>Open the <span class="tab-ref">Joint Control</span> tab. Command a fast move (high speed) and observe the behaviour. Then set speed to 20% and repeat. Describe the difference in collision risk.</li>\n      <li>Write a short (half-page) <strong>safe operating procedure (SOP)</strong> for using this arm in your lab. Include: who may operate it, pre-use checks, what to do if something goes wrong, and how to safely power it down.</li>\n    </ul>\n    <div class="callout callout-tip no-print">\n      <span class="callout-icon">📋</span>\n      <div class="callout-body">\n        <strong>SOP Template - Connection and Control Workflow</strong></br>\n        Your SOP should include this specific sequence for using the application safely:\n        <ol style="margin:0.4rem 0 0;padding-left:1.2rem;">\n          <li>Open the application, navigate to <span class="ui-ref">Connection</span> tab, enter the onboard computer\'s IP address (or use Auto-Detect), connect</li>\n          <li>Observe the LED strip - confirm it shows <strong>solid green</strong> (connected and ready) before proceeding</li>\n          <li>Press <strong>Take Control</strong> - confirm the status bar shows you have control</li>\n          <li>Enable torque only when ready to move and everyone is clear of the working envelope</li>\n          <li>After completing work: press <strong>E-Stop</strong> or run the Home sequence, then <strong>Disable Torque</strong>, then press <strong>Release Control</strong></li>\n          <li>Do not leave the session with control held - another user will be locked out</li>\n        </ol>\n      </div>\n    </div>\n    <h3>Hazard Register</h3>\n    <table>\n      <tr><th>Hazard</th><th>Who is at risk</th><th>Existing controls</th><th>Hierarchy level</th><th>Residual risk</th></tr>\n      <tr>\n        <td><input type="text" placeholder="1."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n      <tr>\n        <td><input type="text" placeholder="2."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n      <tr>\n        <td><input type="text" placeholder="3."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n    </table>\n    <div class="ws-field">\n      <label>Servo protection values (Calibration tab, Joint 2) - Max torque, Protection current, Overload torque</label>\n      <input type="text" placeholder="Max torque: ___   Protection current: ___   Overload torque: ___">\n    </div>\n    <div class="ws-field">\n      <label>Speed comparison - high speed vs 20% (collision risk)</label>\n      <textarea placeholder="At high speed... At 20%..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>Safe Operating Procedure (SOP)</label>\n      <textarea style="min-height:140px;" placeholder="Who may operate: ...&#10;Pre-use checks: ...&#10;If something goes wrong: ...&#10;Safe power-down: ..."></textarea>\n    </div>\n    <div class="callout callout-info no-print">\n      <span class="callout-icon">⚙️</span>\n      <div class="callout-body">\n        <strong>Where the safety-relevant settings live</strong></br>\n        There is no single settings page - each control sits where it is used:\n        <ul style="margin:0.4rem 0 0;padding-left:1.2rem;">\n          <li><strong>Speed</strong>: set per move - the speed control in <span class="ui-ref">Joint Control</span> / <span class="ui-ref">Pendant Control</span>, the <code>F</code> feed rate in G-code, or the speed argument of a RAPID / Blockly move</li>\n          <li><strong>Movement Mode</strong>: PTP (faster, curved tool path) or Linear Cartesian (straight-line tool path, slower, with its own tool speed in mm/s) on the <span class="ui-ref">Pendant Control</span> tab</li>\n          <li><strong>Dead Zones</strong>: XYZ regions the arm must not enter, on the <span class="ui-ref">Dead Zones</span> tab</li>\n          <li><strong>Servo protection thresholds</strong>: Max torque, Protection current, Overload torque and Protection time, stored in each servo\'s EEPROM and shown on the <span class="ui-ref">Calibration</span> tab (password needed to change)</li>\n          <li><strong>Joint angle limits</strong>: Min/Max angle limit in the same EEPROM table, set from the arm\'s URDF during commissioning</li>\n          <li><strong>Status updates</strong>: fixed at about 20 ms - not adjustable</li>\n        </ul>\n        There is no explicit current-limit slider - the ST3215 servo\'s current limit is a hardware parameter. The closest everyday software safety control for overload is the <strong>speed</strong> you choose: lower speed → lower peak current draw → lower risk of thermal overload.\n      </div>\n    </div>\n  </div>',

  'module-15.html': '<div class="section-card worksheet-card">\n    <span class="pill pill-worksheet">Worksheet</span>\n    <h2>Worksheet 15 - Maintenance &amp; Calibration</h2>\n    <h3>1. Activity 15A - Inspection record</h3>\n    <div class="table-scroll">\n      <table>\n        <tr><th>Check</th><th>Result (OK / Fault)</th><th>Notes / action needed</th></tr>\n        <tr><td>Fixings, servo horns and brackets</td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>Bus cables and connectors</td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>Play / backlash in each joint</td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>Gripper / end effector</td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>Base fixed to bench</td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>Servo temperatures (all joints)</td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>Supply voltage at servos</td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>Bus diagnostics (Connection tab)</td><td><input type="text"></td><td><input type="text"></td></tr>\n      </table>\n    </div>\n    <div class="ws-field">\n      <label>2. Describe three environmental conditions in your workshop that could affect the arm, and how you would control each one.</label>\n      <textarea placeholder="Condition 1: ... Control: ...&#10;Condition 2: ... Control: ...&#10;Condition 3: ... Control: ..."></textarea>\n    </div>\n    <h3>3. Activity 15B - Servo register values</h3>\n    <div class="table-scroll">\n      <table>\n        <tr><th>Joint</th><th>Position correction (0x1F)</th><th>Min angle limit (0x09)</th><th>Max angle limit (0x0B)</th><th>Other changed values</th></tr>\n        <tr><td>1</td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>2</td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>3</td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>4</td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>5</td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td>6</td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n      </table>\n    </div>\n    <div class="ws-field">\n      <label>4. What is the difference between the EEPROM and SRAM tables? Why are the servo ID and baud rate locked even for the instructor?</label>\n      <textarea placeholder="EEPROM is... SRAM is...&#10;ID and baud rate are locked because..."></textarea>\n    </div>\n    <h3>5. Activity 15C - Calibration record</h3>\n    <div class="table-scroll">\n      <table>\n        <tr><th>Item</th><th>Value</th></tr>\n        <tr><td>Joint calibrated</td><td><input type="text"></td></tr>\n        <tr><td>As found: reading with marks aligned (zero error, °)</td><td><input type="text"></td></tr>\n        <tr><td>Trim set (°)</td><td><input type="text"></td></tr>\n        <tr><td>Verify from +30°: marks aligned? (Y/N, error)</td><td><input type="text"></td></tr>\n        <tr><td>Verify from -30°: marks aligned? (Y/N, error)</td><td><input type="text"></td></tr>\n        <tr><td>Reading after Reset (°)</td><td><input type="text"></td></tr>\n        <tr><td>Calibrated by / checked by / date</td><td><input type="text"></td></tr>\n      </table>\n    </div>\n    <div class="ws-field">\n      <label>6. Was there a difference between approaching zero from +30° and from -30°? What causes this, and what does it mean for how precisely a joint can be calibrated?</label>\n      <textarea placeholder="Difference: ...&#10;Cause: ...&#10;This means..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>7. Explain why a 1° zero error on the shoulder joint affects every stored position and every XYZ move. Estimate the error at the tool tip if the arm reaches 300 mm.</label>\n      <textarea placeholder="Because... Error at the tip ≈ 300 mm × (1° in radians) = ___ mm"></textarea>\n    </div>\n    <div class="ws-field">\n      <label>8. Compare the trainee trim with writing the servo\'s Position Correction register. Give one advantage and one disadvantage of each.</label>\n      <textarea placeholder="Trainee trim - advantage: ...  disadvantage: ...&#10;Position Correction - advantage: ...  disadvantage: ..."></textarea>\n    </div>\n    <h3>9. Spares list for one year of classroom use</h3>\n    <div class="table-scroll">\n      <table>\n        <tr><th>Part</th><th>Quantity</th><th>Reason (wears / fails / long lead time)</th></tr>\n        <tr><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n        <tr><td><input type="text"></td><td><input type="text"></td><td><input type="text"></td></tr>\n      </table>\n    </div>\n    <div class="ws-field">\n      <label>10. Write a standard operating procedure for replacing a faulty servo on this arm. Include: scope, hazards and PPE, safe isolation, tools and parts, numbered steps (including setting the servo ID, commissioning and calibrating the zero), an acceptance test, and what to record.</label>\n      <textarea style="min-height:180px;" placeholder="Title and scope: ...&#10;Hazards and PPE: ...&#10;Isolation: ...&#10;Tools and parts: ...&#10;Steps: 1. ...&#10;Acceptance test: ...&#10;Records: ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>11. Propose a preventive maintenance schedule for the arm (daily / weekly / termly checks). How would you judge whether the schedule is effective after a year?</label>\n      <textarea placeholder="Daily: ...&#10;Weekly: ...&#10;Termly: ...&#10;Effectiveness: I would measure..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>12. Extension: Research how one industrial robot manufacturer (e.g. ABB, FANUC, KUKA, Yaskawa) masters its robots. Compare their method with the alignment-mark method you used.</label>\n      <textarea placeholder="Manufacturer: ...&#10;Their method: ...&#10;Comparison: ..."></textarea>\n    </div>\n  </div>',

  'module-16.html': '<div class="section-card worksheet-card">\n    <span class="pill pill-worksheet">Worksheet</span>\n    <h2>Activity - Plan Your Robot Arm Project</h2>\n    <p>You will create a project plan for your own robot arm assignment. This plan will guide your work in Modules 17 and 18.</p>\n    <ul class="steps">\n      <li>Write a <strong>project brief</strong> in 3–5 sentences: what you are going to make the arm do, who it is for, and what success looks like.</li>\n      <li>List at least <strong>six measurable specification points</strong> (mix of essential and desirable) covering: performance, safety, software, and documentation.</li>\n      <li>Identify at least <strong>three risks</strong> to your project (technical or practical) and write a mitigation for each.</li>\n      <li>Draw a <strong>Gantt chart</strong> on paper or in a spreadsheet, mapping your six project phases across the weeks available. Identify any parallel tasks.</li>\n      <li>Share your plan with a classmate for peer review. Ask them: Is the brief clear? Are the spec points measurable? Is the timeline realistic?</li>\n      <li>Update your plan based on their feedback and keep it as a living document - revise it as the project progresses.</li>\n    </ul>\n    <div class="callout callout-tip no-print">\n      <span class="callout-icon">🔧</span>\n      <div class="callout-body">\n        <strong>Extension Scope - End-Tool Subsystem</strong></br>\n        If you want a more advanced project, include the end-tool subsystem (gripper or vacuum pump) in your specification. Additional specification points could include:\n        <ul style="margin:0.4rem 0 0;padding-left:1.2rem;">\n          <li>"Gripper closes to a consistent angle within <strong>±5°</strong> across 10 operations" - verify via the End Tool Servo panel in <span class="ui-ref">Joint Control</span></li>\n          <li>"Vacuum pump maintains suction for at least <strong>10 seconds</strong> without pressure loss" - verify by timing grip duration during the pick operation</li>\n        </ul>\n        The end-tool controls (<code>GripperOpen</code>, <code>GripperClose</code>, <code>PumpOn</code>, <code>PumpOff</code>) are available in all three programming modes (G-Code: <code>M10</code>/<code>M11</code>; RAPID: named commands; Blockly: dedicated blocks).\n      </div>\n    </div>\n    <div class="ws-field">\n      <label>Project brief (3–5 sentences)</label>\n      <textarea style="min-height:100px;" placeholder="What the arm will do, who it is for, and what success looks like..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>Specification points (at least six, measurable)</label>\n      <textarea style="min-height:120px;" placeholder="1. ...&#10;2. ...&#10;3. ..."></textarea>\n    </div>\n    <h3>Risk Register</h3>\n    <table>\n      <tr><th>Risk</th><th>Likelihood (H/M/L)</th><th>Impact (H/M/L)</th><th>Mitigation</th></tr>\n      <tr>\n        <td><input type="text" placeholder="1."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n      <tr>\n        <td><input type="text" placeholder="2."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n      <tr>\n        <td><input type="text" placeholder="3."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n    </table>\n    <div class="ws-field">\n      <label>Peer review notes and plan updates</label>\n      <textarea placeholder="Feedback received: ...&#10;Changes made: ..."></textarea>\n    </div>\n    <div class="callout callout-warning no-print">\n      <span class="callout-icon">⚠️</span>\n      <div class="callout-body">\n        <strong>Risk Register - Software-Specific Risks to Include</strong></br>\n        <ul style="margin:0.4rem 0 0;padding-left:1.2rem;">\n          <li><strong>Risk: Control session contention</strong> - two students try to command the arm simultaneously. Likelihood: Medium. Mitigation: single-client enforcement by the server; 5-minute idle timeout; communicate who has control before switching operators.</li>\n          <li><strong>Risk: Network drop mid-move</strong> - the app loses connection while a G-code sequence is running. Likelihood: Low. Mitigation: the server continues executing buffered commands; reconnect immediately and issue Stop All from the <span class="ui-ref">G-Code Control</span> tab.</li>\n          <li><strong>Risk: Serial bus loss during pick</strong> - the server loses contact with the servo bus while gripping. Likelihood: Very Low. Mitigation: auto-recovery occurs within 30 s; always Home before starting a new sequence to confirm arm position.</li>\n        </ul>\n      </div>\n    </div>\n  </div>',

  'module-17.html': '<div class="section-card worksheet-card">\n    <span class="pill pill-worksheet">Worksheet</span>\n    <h2>Activity - Document Your Project</h2>\n    <p>Produce a documentation pack for your robot arm project. Use the checklist below to ensure nothing is missing.</p>\n    <ul class="steps">\n      <li><strong>Block diagram:</strong> Draw a system block diagram showing all hardware components (onboard computer, servos, sensors, PSU, app) and how they connect. Label each connection with the protocol used (UART, WebSocket, I²C, etc.).</li>\n      <li><strong>Annotated program:</strong> Take your G-code or Blockly program from Module 13 and add annotations explaining each section - what it does and why (not line-by-line, just the important parts).</li>\n      <li><strong>Test record:</strong> Design three tests against your specification points (from Module 16). Run each test, record actual results, and state pass/fail against the specification.</li>\n      <li><strong>User guide:</strong> Write a one-page user guide for operating your arm program. Assume the reader has never used the app. Include: how to connect, how to run the program, what to do if it does not work, how to shut down safely.</li>\n      <li><strong>Revision log:</strong> Add a short revision history table to each document: date, version number, and what changed.</li>\n    </ul>\n    <div class="callout callout-tip no-print">\n      <span class="callout-icon">🤖</span>\n      <div class="callout-body">\n        <strong>RAPID as an Alternative to G-Code for Annotated Code</strong></br>\n        For the "annotated code" document, you may use a RAPID script from the <span class="ui-ref">RAPID</span> tab instead of G-code. RAPID is closer to real industrial robot programming languages and produces a stronger portfolio artefact. The annotation requirement is the same: each <code>MoveJ</code>, <code>MoveLXYZ</code>, or <code>GripperClose</code> line must be commented with the physical action it performs, the reason for the speed choice, and any safety consideration. A well-annotated RAPID program demonstrates professional programming practice.\n      </div>\n    </div>\n    <h3>Documentation Pack Checklist</h3>\n    <ul class="checklist">\n      <li><label><input type="checkbox"> System block diagram - all components, all connections labelled</label></li>\n      <li><label><input type="checkbox"> Annotated G-code, Blockly, or RAPID program</label></li>\n      <li><label><input type="checkbox"> Three completed test records with actual measurements</label></li>\n      <li><label><input type="checkbox"> One-page user guide / SOP</label></li>\n      <li><label><input type="checkbox"> Risk assessment (from Module 14)</label></li>\n      <li><label><input type="checkbox"> Project plan / Gantt chart (from Module 16)</label></li>\n      <li><label><input type="checkbox"> Revision history on each document</label></li>\n    </ul>\n    <div class="ws-field">\n      <label>Test 1 - description, result, pass/fail</label>\n      <textarea placeholder="Spec point: ...&#10;Method: ...&#10;Result: ...&#10;Pass / Fail:"></textarea>\n    </div>\n    <div class="ws-field">\n      <label>Test 2 - description, result, pass/fail</label>\n      <textarea placeholder="Spec point: ...&#10;Method: ...&#10;Result: ...&#10;Pass / Fail:"></textarea>\n    </div>\n    <div class="ws-field">\n      <label>Test 3 - description, result, pass/fail</label>\n      <textarea placeholder="Spec point: ...&#10;Method: ...&#10;Result: ...&#10;Pass / Fail:"></textarea>\n    </div>\n    <div class="ws-field">\n      <label>Notes / gaps still to complete</label>\n      <textarea placeholder="Anything still missing from the documentation pack..."></textarea>\n    </div>\n  </div>',

  'module-18.html': '<div class="section-card worksheet-card">\n    <span class="pill pill-worksheet">Worksheet</span>\n    <h2>Activity - Evaluate and Present Your Project</h2>\n    <p>Complete these tasks to finalise your project and prepare for assessment.</p>\n    <ul class="steps">\n      <li><strong>Specification review:</strong> Return to the specification you wrote in Module 16. For each point, record the actual outcome (your test results from Module 17) and state pass or fail.</li>\n      <li><strong>Written evaluation:</strong> For each specification point, write 2–4 sentences covering outcome, analysis, and improvement (use the table format from Theory 2 above as a guide).</li>\n      <li><strong>Overall reflection:</strong> Write one paragraph (150–200 words) answering: What were the two most significant technical challenges you faced, and how did you overcome them?</li>\n      <li><strong>Future development:</strong> Write three specific, justified improvements you would make if you had more time. For each, explain the engineering reason it would improve the system.</li>\n      <li><strong>Presentation:</strong> Prepare a 5-minute presentation of your project. Include: what the arm was programmed to do, a live demonstration, two key results from testing, and one honest critique of your own work.</li>\n      <li><strong>Non-technical summary:</strong> Write a half-page plain-English summary of your project, suitable for a parent, governor, or potential employer who has no engineering background.</li>\n    </ul>\n    <div class="callout callout-tip no-print">\n      <span class="callout-icon">💭</span>\n      <div class="callout-body">\n        <strong>Evaluation Prompt - Programming Mode Choice</strong></br>\n        Write a paragraph addressing this question: <em>"Which programming mode (Blockly, G-Code, or RAPID) was most effective for your project, and why? If you were building a pick-and-place system that needed to respond to the camera (pick the block the camera detects, not a pre-taught position), which mode would you use and what would need to change in either the app or the server to support it?"</em>\n        <br><br>\n        A strong answer names specific advantages and limitations of the chosen mode, references actual observations from the project (e.g. "G-code was faster to edit when I needed to adjust a single position"), and proposes a technically plausible change for the camera-reactive scenario.\n      </div>\n    </div>\n    <div class="callout callout-tip no-print">\n      <span class="callout-icon">📐</span>\n      <div class="callout-body">\n        <strong>Improvement Topic - 3D Model Calibration</strong></br>\n        Evaluate how accurately the 3D Visualisation model matched the physical arm\'s end-effector position during your project. Consider: did the model diverge from the physical arm at extreme joint configurations? Possible causes: joint flex under load, mechanical backlash, or inaccurate link lengths in the URDF.\n        <br><br>\n        A strong improvement proposal would be: <em>"The URDF link lengths could be refined by commanding 10 known positions, measuring the actual end-effector XYZ with a ruler and reference frame, comparing to the FK-computed values, and adjusting the URDF until the error is below ±5 mm. The AS5600 encoders provide a second angle reference that could also be used to detect systematic backlash errors."</em>\n        This demonstrates understanding of the URDF (the <strong>View the URDF file</strong> link on the Kinematics tab), the Kinematics tab\'s transform matrices, and the AS5600 hardware - an engineering improvement rooted in the specific system.\n      </div>\n    </div>\n    <div class="callout callout-tip no-print">\n      <span class="callout-icon">🎯</span>\n      <div class="callout-body">\n        <strong>Live Demo Suggestion - Control Session Handover</strong></br>\n        For a memorable and technically impressive demonstration, show the <strong>control session handover</strong>:\n        <ol style="margin:0.4rem 0 0;padding-left:1.2rem;">\n          <li>Your computer has control - run a short automated sequence</li>\n          <li>A second student connects on a second laptop - show the "another client has control" status message on their screen</li>\n          <li>Demonstrate <strong>Force Take Control</strong> from the second laptop - your session is displaced and you are notified</li>\n          <li>The second student now commands the arm</li>\n        </ol>\n        This demonstrates a real distributed-system concept (mutual exclusion over a network) to examiners - not just "the arm moves to a position". It directly showcases knowledge from Module 9 (WebSocket architecture) and Module 14 (control session as an engineering control), and is unique to this specific system.\n      </div>\n    </div>\n    <h3>Evaluation Summary Table</h3>\n    <table>\n      <tr><th>Spec point</th><th>Target</th><th>Actual result</th><th>Pass/Fail</th><th>Key reason for outcome</th></tr>\n      <tr>\n        <td><input type="text" placeholder="1."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n      <tr>\n        <td><input type="text" placeholder="2."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n      <tr>\n        <td><input type="text" placeholder="3."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n      <tr>\n        <td><input type="text" placeholder="4."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n      <tr>\n        <td><input type="text" placeholder="5."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n      <tr>\n        <td><input type="text" placeholder="6."></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n        <td><input type="text"></td>\n      </tr>\n    </table>\n    <div class="ws-field">\n      <label>Overall reflection (150–200 words)</label>\n      <textarea style="min-height:120px;" placeholder="Two most significant technical challenges and how you overcame them..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>Future development - three justified improvements</label>\n      <textarea style="min-height:120px;" placeholder="1. ...&#10;2. ...&#10;3. ..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>Programming mode evaluation (optional prompt)</label>\n      <textarea placeholder="Which mode was most effective and why? Camera-reactive scenario..."></textarea>\n    </div>\n    <div class="ws-field">\n      <label>Non-technical summary (plain English)</label>\n      <textarea style="min-height:100px;" placeholder="Half-page summary for a non-engineer audience..."></textarea>\n    </div>\n  </div>'
};
